def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in ``[start, finish]`` ending in ``s`` whose
    digits are all at most ``limit``.

    The fixed suffix leaves only a (possibly empty) digit prefix to count.
    Counting prefixes by length and using a digit bound avoids iterating over
    the potentially very large input range.
    """
    if start > finish or finish < 1:
        return 0
    if not s or not s.isdigit():
        raise ValueError("s must be a non-empty string of decimal digits")
    if not 1 <= limit <= 9:
        raise ValueError("limit must be between 1 and 9")

    # Every matching integer contains these suffix digits, so one disallowed
    # suffix digit makes the answer zero.
    if any(int(digit) > limit for digit in s):
        return 0

    suffix_length = len(s)

    def all_prefixes(prefix_length: int) -> int:
        """Count positive, fixed-width prefixes with digits in [0, limit]."""
        if prefix_length == 0:
            return 1
        return limit * (limit + 1) ** (prefix_length - 1)

    def prefixes_less_than(bound: str) -> int:
        """Count valid fixed-width prefixes lexicographically below bound."""
        total = 0
        width = len(bound)
        for index, character in enumerate(bound):
            bound_digit = int(character)
            min_digit = 1 if index == 0 else 0
            choices = max(0, min(limit, bound_digit - 1) - min_digit + 1)
            if choices:
                total += choices * (limit + 1) ** (width - index - 1)

            # The bound itself is no longer a valid continuation; the smaller
            # prefixes counted above are still valid.
            if bound_digit < min_digit or bound_digit > limit:
                return total
        # The loop's branches count smaller values only (not the bound itself).
        return total

    def prefix_is_valid(prefix: str) -> bool:
        return bool(prefix) and prefix[0] != "0" and all(
            int(digit) <= limit for digit in prefix
        )

    def count_at_most(number: int) -> int:
        if number < 1:
            return 0
        bound = str(number)
        bound_length = len(bound)
        if suffix_length > bound_length:
            return 0

        total = 0
        # All shorter numbers are automatically below number.
        for length in range(suffix_length, bound_length):
            prefix_length = length - suffix_length
            if prefix_length == 0:
                # An integer's ordinary decimal representation cannot start
                # with zero, even if the supplied suffix string does.
                if s[0] != "0":
                    total += 1
            else:
                total += all_prefixes(prefix_length)

        prefix_length = bound_length - suffix_length
        if prefix_length == 0:
            # The only number of this length with this suffix is s itself.
            if s[0] != "0" and int(s) <= number:
                total += 1
            return total

        prefix_bound = bound[:prefix_length]
        suffix_bound = bound[prefix_length:]
        total += prefixes_less_than(prefix_bound)
        if s <= suffix_bound and prefix_is_valid(prefix_bound):
            total += 1
        return total

    return count_at_most(finish) - count_at_most(start - 1)

from math import gcd
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive multiple of any given denomination.

    Different denominations cannot be combined. Denominations are positive,
    and k is a positive, one-based index. The input list is not modified.

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # Multiples of a redundant denomination are already supplied by a smaller
    # denomination, so they do not change the set of available amounts.
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    if len(denominations) == 1:
        return denominations[0] * k

    low, high = denominations[0], denominations[0] * k

    # Aggregate inclusion-exclusion terms by their LCM. Every subset contributes
    # +1 for odd size or -1 for even size. LCMs above high cannot contribute to
    # a count in the search interval, nor can any of their supersets.
    coefficients = {}
    for coin in denominations:
        additions = {coin: 1}
        for multiple, coefficient in coefficients.items():
            common = multiple // gcd(multiple, coin) * coin
            if common <= high:
                additions[common] = additions.get(common, 0) - coefficient
        for multiple, coefficient in additions.items():
            combined = coefficients.get(multiple, 0) + coefficient
            if combined:
                coefficients[multiple] = combined
            else:
                coefficients.pop(multiple, None)

    terms = tuple(coefficients.items())
    while low < high:
        middle = (low + high) // 2
        count = sum(coefficient * (middle // multiple)
                    for multiple, coefficient in terms)
        if count >= k:
            high = middle
        else:
            low = middle + 1
    return low

from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in ``[low, high]`` with equally many even and odd digits
    that are divisible by ``k``.

    Args:
        low: Inclusive lower bound (``0 < low <= high <= 10**9``).
        high: Inclusive upper bound.
        k: Positive divisor (at most 20).

    Returns:
        The number of beautiful integers in the range.
    """

    def count_up_to(limit: int) -> int:
        if limit <= 0:
            return 0

        digits = tuple(map(int, str(limit)))
        length = len(digits)

        @lru_cache(maxsize=None)
        def visit(position: int, balance: int, remainder: int,
                  tight: bool, started: bool) -> int:
            if position == length:
                return int(started and balance == 0 and remainder == 0)

            max_digit = digits[position] if tight else 9
            total = 0
            for digit in range(max_digit + 1):
                next_tight = tight and digit == max_digit
                if not started and digit == 0:
                    # Leading zeroes are not digits of the number.
                    total += visit(position + 1, 0, 0, next_tight, False)
                else:
                    # A zero is even, as are 2, 4, 6, and 8.
                    next_balance = balance + (1 if digit % 2 == 0 else -1)
                    next_remainder = (remainder * 10 + digit) % k
                    total += visit(
                        position + 1,
                        next_balance,
                        next_remainder,
                        next_tight,
                        True,
                    )
            return total

        return visit(0, 0, 0, True, False)

    return count_up_to(high) - count_up_to(low - 1)

from math import lcm
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th smallest positive amount divisible by a coin denomination.

    Each denomination contributes its positive multiples to the set of amounts.
    An amount divisible by multiple denominations is counted only once.

    Args:
        coins: Distinct positive coin denominations.
        k: 1-based position in the ordered set of possible amounts.

    Returns:
        The k-th smallest amount that is a multiple of at least one denomination.
    """
    # Inclusion-exclusion computes the size of the union of the sets of
    # multiples. Group equal LCMs to reduce work when denominations overlap.
    lcm_coefficients = {}
    n = len(coins)
    for mask in range(1, 1 << n):
        common_multiple = 1
        bits = 0
        for i, coin in enumerate(coins):
            if mask & (1 << i):
                common_multiple = lcm(common_multiple, coin)
                bits += 1
        sign = 1 if bits % 2 else -1
        lcm_coefficients[common_multiple] = lcm_coefficients.get(common_multiple, 0) + sign

    def count_at_most(amount: int) -> int:
        return sum(
            coefficient * (amount // common_multiple)
            for common_multiple, coefficient in lcm_coefficients.items()
            if common_multiple <= amount and coefficient
        )

    # The k-th multiple of the smallest denomination is always an upper bound.
    low, high = 1, min(coins) * k
    while low < high:
        middle = (low + high) // 2
        if count_at_most(middle) >= k:
            high = middle
        else:
            low = middle + 1
    return low

